private async normalizarEntrada(entrada: CanalEntrada): Promise<{ turno: TurnoUnificado; responderEmVoz: boolean }> {
  const agora = new Date().toISOString();
  switch (entrada.tipo) {
    case 'texto':
      return { responderEmVoz: false, turno: { role: 'user', timestampISO: agora, textoCanonico: entrada.conteudo.trim() } };
    case 'audio': {
      const stt = await openai.audio.transcriptions.create({
        file: fs.createReadStream(entrada.caminhoArquivo), model: 'whisper-1', language: 'pt',
      });
      return { responderEmVoz: true, turno: { role: 'user', timestampISO: agora, textoCanonico: `[VOZ (${entrada.duracaoSegundos}s)]: ${stt.text}` } };
    }
    case 'imagem': {
      const norm = await normalizarFotoDocumento(entrada.buffer);
      const dataUri = `data:${norm.mimeType};base64,${norm.buffer.toString('base64')}`;
      const legenda = entrada.legenda ? ` Legenda: "${entrada.legenda}".` : '';
      return { responderEmVoz: false, turno: { role: 'user', timestampISO: agora, textoCanonico: `[FOTO ANEXADA].${legenda}`, imagemDataUri: dataUri } };
    }
    case 'pdf':
      return { responderEmVoz: false, turno: { role: 'user', timestampISO: agora, textoCanonico: `[PDF ${entrada.nomeArquivo}]\n${entrada.conteudoExtraido}` } };
  }
}

