export interface EventoExtracaoTelemetry {
  documentHash: string;
  pageCount: number;
  tokenUsage: { inputTokens: number; outputTokens: number };
  latencyMs: number;
  auditoriaValida: boolean;
  custoEstimadoUsd: number;
}

export function calcularCustoDocUsd(pageCount: number, tokensPorPag: number, tokensSaida: number, cInPorMilhao: number, cOutPorMilhao: number): number {
  const custoEntrada = ((pageCount * tokensPorPag) * cInPorMilhao) / 1_000_000;
  const custoSaida = (tokensSaida * cOutPorMilhao) / 1_000_000;
  return Number((custoEntrada + custoSaida).toFixed(6));
}

export function registrarTelemetriaSegura(evt: EventoExtracaoTelemetry, telemetryClient: { track: (name: string, data: EventoExtracaoTelemetry) => void }) {
  telemetryClient.track('ocr.document.completed', evt);
}
